function FormRow({
  label,
  children,
  align = 'center',
  labelOffset,
}: {
  label: string;
  children: React.ReactNode;
  align?: 'center' | 'start';
  labelOffset?: number;
}) {
  const pt = labelOffset !== undefined ? labelOffset : (align === 'start' ? 2 : 0);
  return (
    <div style={{
      display: 'grid',
      gridTemplateColumns: `${LABEL_COL} auto`,
      columnGap: 20,
      alignItems: align,
    }}>
      <span style={{ ...labelStyle, paddingTop: pt }}>{label}</span>
      <div>{children}</div>
    </div>
  );
}

