        <div style={{ display: 'flex', flexDirection: 'column', gap: 30, paddingRight: 20 }}>

        {/* ── Notify when + Notification frequency (20px apart) ──────── */}
        <div style={{ display: 'flex', flexDirection: 'column', gap: 20 }}>
        <div style={{
