            <Dropdown
              layout="vertical"
              placeholder="Select Feature"
              options={METRIC_OPTIONS}
              width={metricW}
              value={metric}
              onChange={(v) => {
                setMetric(v);
                setOperator('');
                setThreshold('');
                setRollingHours('');
                if (v in METRIC_UNIT_OPTIONS) {
                  setPercentageValue('80');
                  setPercentageUnit('percentage');
                } else {
                  setPercentageValue('');
                }
              }}
            />
            <Dropdown
              layout="vertical"
              placeholder="Select Condition"
              options={OPERATOR_OPTIONS}
              width={operatorW}
              value={operator}
              onChange={(v) => {
                setOperator(v);
                setThreshold('');
                if (v === 'anomaly_detected') {
                  setPercentageValue('');
                  setRollingHours('');
                }
              }}
