                    }}>
                      {/* Show committed values as Tags chips; overlay intercepts clicks to open sub-modal */}
                      <div style={{ position: 'relative', width: 390 }}>
                        <Tags
                          value={[...zohoCommittedUsers, ...zohoCommittedChannels]}
